sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.collapsed = false;

    c.toggleSidebar = function() {

        c.collapsed = !c.collapsed;

    };

};

sp_widget.css:
.automed-sidebar {

    width: 260px;
    height: 100vh;

    background: #FFFFFF;

    border-right: 1px solid #E5E7EB;

    box-shadow: 0 0 20px rgba(0,0,0,.05);

    transition: all .3s ease;

    overflow: hidden;

    position: fixed;

    top: 0;
    left: 0;

    z-index: 1000;

}

/* COLLAPSED */

.automed-sidebar.collapsed {

    width: 75px;

}

/* HEADER */

.sidebar-header {

    display: flex;

    align-items: center;

    justify-content: space-between;

    padding: 20px;

}

.logo-section {

    display: flex;

    align-items: center;

    gap: 12px;

}

.logo-icon {

    color: #2563EB;

    font-size: 28px;

}

.logo-text {

    font-size: 22px;

    font-weight: 700;

    color: #111827;

}

/* BUTTON */

.toggle-btn {

    border: none;

    background: #F3F4F6;

    width: 36px;

    height: 36px;

    border-radius: 8px;

    cursor: pointer;

}

.toggle-btn:hover {

    background: #E5E7EB;

}

/* USER CARD */

.user-card {

    display: flex;

    align-items: center;

    gap: 12px;

    margin: 15px;

    padding: 15px;

    background: #F9FAFB;

    border-radius: 12px;

}

.avatar {

    width: 45px;

    height: 45px;

    border-radius: 50%;

    background: #2563EB;

    color: white;

    display: flex;

    align-items: center;

    justify-content: center;

    font-weight: bold;

}

.user-name {

    font-weight: 600;

    color: #111827;

}

.user-role {

    color: #6B7280;

    font-size: 12px;

}

/* MENU */

.menu-list {

    list-style: none;

    margin: 0;

    padding: 10px;

}

.menu-list li {

    margin-bottom: 8px;

}

.menu-list li a {

    display: flex;

    align-items: center;

    gap: 15px;

    text-decoration: none;

    color: #4B5563;

    padding: 14px;

    border-radius: 12px;

    transition: all .3s ease;

}

.menu-list li a:hover {

    background: #F3F4F6;

    color: #2563EB;

    transform: translateX(4px);

}

.menu-list li.active a {

    background: #2563EB;

    color: white;

    font-weight: 600;

    box-shadow: 0 8px 20px rgba(37,99,235,.25);

}

.menu-list li i {

    width: 20px;

    text-align: center;

}

/* COLLAPSED STATE */

.automed-sidebar.collapsed .logo-text {

    display: none;

}

.automed-sidebar.collapsed .user-details {

    display: none;

}

.automed-sidebar.collapsed .menu-list span {

    display: none;

}

.automed-sidebar.collapsed .user-card {

    justify-content: center;

}

/* MOBILE */

@media(max-width:768px){

    .automed-sidebar{

        width:75px;

    }

}

sp_widget.script:
(function() {

    data.userName = gs.getUserDisplayName();
    data.currentPage = $sp.getParameter('id');
    data.roleName = '';
    data.menuItems = [];

    if (gs.hasRole('x_snc_trackmed.organization_admin')) {

        data.roleName = 'Organization Admin';

        data.menuItems = [
            {
                name: 'Dashboard',
                page: 'org_dashboard',
                icon: 'fa fa-home'
            },
            {
                name: 'Hospitals',
                page: 'org_hospitals',
                icon: 'fa fa-building'
            },
            {
                name: 'Users',
                page: 'org_users',
                icon: 'fa fa-users'
            },
            {
                name: 'Reports',
                page: 'org_reports',
                icon: 'fa fa-bar-chart'
            }
        ];
    }

    else if (gs.hasRole('x_snc_trackmed.hospital_admin')) {

        data.roleName = 'Hospital Admin';

        data.menuItems = [
            {
                name: 'Dashboard',
                page: 'hospital_dashboard',
                icon: 'fa fa-home'
            },
            {
                name: 'Doctors',
                page: 'hospital_doctors',
                icon: 'fa fa-user-md'
            },
            {
                name: 'Patients',
                page: 'hospital_patients',
                icon: 'fa fa-users'
            },
            {
                name: 'Reports',
                page: 'hospital_reports',
                icon: 'fa fa-bar-chart'
            }
        ];
    }

    else if (gs.hasRole('x_snc_trackmed.doctor')) {

        data.roleName = 'Doctor';

        data.menuItems = [
            {
                name: 'Dashboard',
                page: 'doctor_dashboard',
                icon: 'fa fa-home'
            },
            {
                name: 'My Patients',
                page: 'doctor_patients',
                icon: 'fa fa-users'
            },
            {
                name: 'Prescriptions',
                page: 'doctor_prescriptions',
                icon: 'fa fa-medkit'
            },
            {
                name: 'Appointments',
                page: 'doctor_appointments',
                icon: 'fa fa-calendar'
            }
        ];
    }

    else if (gs.hasRole('x_snc_trackmed.caregiver')) {

        data.roleName = 'Caregiver';

        data.menuItems = [
            {
                name: 'Dashboard',
                page: 'caregiver_dashboard',
                icon: 'fa fa-home'
            },
            {
                name: 'Patients',
                page: 'caregiver_patients',
                icon: 'fa fa-users'
            },
            {
                name: 'Schedule',
                page: 'caregiver_schedule',
                icon: 'fa fa-clock-o'
            },
            {
                name: 'Medication Logs',
                page: 'caregiver_logs',
                icon: 'fa fa-file-text'
            }
        ];
    }

})();
